typedef ap_fixed<32,10> data_t;
// Production arithmetic revision 2: persistent wide sums.
typedef ap_fixed<80,36,AP_TRN,AP_WRAP> acc_t;
static const int FB_ACC_BITS = 80;
static const int FB_ACC_FRAC = 44;
static acc_t fb_from_code(ap_int<80> code) {
    acc_t result; result.range(79,0) = code; return result;
}
static ap_int<80> fb_code(acc_t x) { return x.range(79,0); }
static acc_t fb_div(acc_t a, acc_t b) {
    assert(b != 0);
    ap_int<160> numerator = fb_code(a);
    numerator <<= 44;
    ap_int<160> denominator = fb_code(b);
    ap_int<160> q = numerator / denominator;
    if ((numerator % denominator) != 0 && ((numerator < 0) != (denominator < 0))) --q;
    return fb_from_code(q);
}
static acc_t fb_sqrt(acc_t x) {
    assert(x >= 0);
    ap_uint<160> value = fb_code(x);
    value <<= 44;
    ap_uint<160> remainder = value, root = 0;
    ap_uint<160> bit = ap_uint<160>(1) << 158;
    for (int i=0; i<80; ++i) {
        if (remainder >= root + bit) { remainder -= root + bit; root = (root >> 1) + bit; }
        else root >>= 1;
        bit >>= 2;
    }
    if (value - root * root > root) ++root;
    return fb_from_code(root);
}
